-- The installed original-funding guard pins the two satellite seat producers.
-- Preserve every check and accept only their exact admitted-club successors.
-- This changes neither the ABI nor business rows, fees, refunds or history.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
DO $preimage$ BEGIN
 IF current_user<>'postgres' OR current_setting('session_replication_role')<>'origin'
    OR (SELECT abi FROM public.ca_mtt_admission_contract WHERE singleton) IS DISTINCT FROM 'legacy-capacity-v1'
    OR (SELECT md5(pg_get_functiondef(p.oid)) FROM pg_proc p
       WHERE p.oid=to_regprocedure('public.fn_ca_guard_mtt_admission_contract()')) IS DISTINCT FROM '2e823d7a1c2c40beee399d6762b7cfbf'
    OR (SELECT pg_get_userbyid(p.proowner) FROM pg_proc p
       WHERE p.oid=to_regprocedure('public.fn_ca_guard_mtt_admission_contract()')) IS DISTINCT FROM 'postgres'
    OR (SELECT array_agg(a::text ORDER BY a::text) FROM pg_proc p CROSS JOIN LATERAL
       unnest(coalesce(p.proacl,acldefault('f',p.proowner)))a
       WHERE p.oid=to_regprocedure('public.fn_ca_guard_mtt_admission_contract()')) IS DISTINCT FROM ARRAY['postgres=X/postgres']::text[] THEN
  RAISE EXCEPTION 'MTT_ACTIVATION_PREPARATION_PREIMAGE_DRIFT' USING ERRCODE='55000';
 END IF;
END $preimage$;
